    const inFrame=state=>{for(const mesh of meshes){
      mesh.geometry.computeBoundingBox();const {min,max}=mesh.geometry.boundingBox;
      for(const x of [min.x,max.x])for(const y of [min.y,max.y])for(const z of [min.z,max.z]){
