        for(const {mesh,parent,matrix} of assemblies){assert.equal(mesh.parent,parent);assert.deepEqual(mesh.matrix.toArray(),matrix);}
        inFrame(`progress ${progress}, quarter turn ${quarter}`);api.rotate();flush();
      }
